B('07高原之谜',[
C('ma_chaowu','马超武','马超武是富豪马多禄的长子，年过三十，仍以少年游荡者的打扮过奢靡生活，和靠半工半读研究地质的弟弟马超文恰成反面。木兰花姐妹为弟弟的异常状态登门，他首先盯上她们的容貌，以轻薄握手接近穆秀珍，手被握痛后便叫保镖殴打来客；父母制止，他又嘲讽弟弟不值得救，放话要让木兰花见识厉害。他并没有经营财富或保护家族的计划，随后策划绑架弟弟，向自己的父母索要大笔赎金，目的仍是供自己挥霍。可是这一场他以为能控制的家庭勒索，被另一伙真正想夺钻石秘密的国际罪犯截走：参与绑架的人遭乱枪杀害，马超文失踪，他自己在交款附近的袭击中昏倒，获木兰花与高翔救活。醒来后仍想否认，直到木兰花用物证与法律后果逼问，才哭着承认。父亲试图用现金摆平失败，他又想逃跑，被勾倒上铐，送去立案。终局没有写判决期限，不因父亲富有就自动免责。这个人物的胆大依赖家庭纵容和雇用者，当身体受制、外部势力介入时，颐指气使很快变成求饶，不能把家中保镖的力量算成他本人的武术。','承认策划绑架弟弟，被高翔逮捕送去立案；最终判刑未写。','三十开外却打扮成少年游荡者，穿紫红上装，神色轻薄。','取得可供挥霍的钱，并维持无需负责的生活。','借家势命令人，出事先否认，无法抵赖时求饶或逃走。','策划家庭勒索、驱使可雇用的帮手；未证明本人有格斗和枪械训练。',[(158,186,'轻薄、依赖保镖与嘲笑弟弟'),(940,1020,'阴谋被截、承认及被捕')],[('他人不接受自己的亲近或要求','自认有家势与保镖撑腰','容易恼羞成怒，试图让别人代自己施压。'),('挥霍需要更多钱','认为亲情一定会促成交赎','可能把家人的感情当成可利用的勒索条件。'),('事情超出原计划且证据指向自己','家长也无法立即摆平','先否认，再求饶或抓机会逃走。')],roles=['反派']),
C('jiang_fangting','蒋方亭','蒋方亭外号飞天狐狸，过去是独来独往的大盗，做过让警方头痛的案子，风声紧时离开城市，后来以心理学博士蒋云霆的身份回来。这个身份有伪装，却不是假学历：他确曾在加拿大认真攻读心理学，随后将上层社会病人的倾诉当成赚钱的秘密来源，把专业信任转成斯文的犯罪手段。马超文探险归来，想确认自己见过的大量钻石是否幻觉，他根据叙述判断探险队中了毒，马与谷柏只是较轻，并且相信那段记忆真实，却故意告诉病人那只是幻象，自己记下路线准备寻宝。木兰花以贵妇身份来试探，他发现异常后用钢笔发射麻醉针，被她以垫子挡住并近身制服，胡子与眼镜也被揭去。她原以为他参与了杀人与绑架，听其辩解并结合旧日作风后，确认主谋另有其人；蒋仍想邀请她分利，自称找到的宝石无主、可以合法取得，不肯接受高原危险的劝告。最后他留在筹划阶段，真正的满溪钻石却被证实只是光照水泡。角色应保留知识与贪欲共存的自欺：专业推断可以局部准确，却不能保证最终对象真实；外号也不代表飞行或狐形能力。','被识破真实身份后供出所知，仍准备自行寻宝；未写实际出发或最终下落。','戴假山羊胡与眼镜的心理医生形象，去除伪装后可认出旧日大盗。','通过专业接触得到的秘密获利，尽量维持斯文而少暴力的形象。','隐瞒关键判断，受揭穿时谈共同利益，承认有限事实。','真实心理学知识、伪装与信息套利、钢笔麻醉针；无读心或强制催眠证据。',[(1040,1104,'诊所试探、麻醉针与被制'),(1114,1148,'身份、真实学历及犯罪方式'),(1152,1202,'毒因判断、骗病人与寻宝计划'),(2472,2488,'所谓钻石的最终真相')],[('来访者向专业人员交出私人经历','其中包含可获利的秘密','可能隐瞒真实看法，让病人退出自己想取得的机会。'),('身份被识破但还可交涉','对方也可能被利益吸引','提出分成而非立即拼命。'),('专业解释支持自己的发财愿望','尚无实物核验','容易把有根据的局部推断扩大成对全部目标的确信。')],roles=['反派','阶段性对立者'],aliases=['蒋云霆','飞天狐狸'],scores={'physical':1,'energy':0,'scope':0,'sustain':1,'range':1,'combat':2},tier='纸',limits='麻醉针须有实际器械且只证实小说中的短期效果；所谓钻石探测仪仅被他说出，未实际演示，不作为确定寻物超能力。'),
C('lei_shenxing','雷慎行','雷慎行是木兰花父亲的朋友，也是成名已久的私家侦探，因戴着五角形红宝石戒指而有红星神将的外号。他在犯罪学、心理学与侦查方面确有修养，破过棘手案件，却也心胸狭窄，已经很久没有生意上门。马多禄请他调查儿子异常，他派助手守在马宅，查出马超文连续几晚外出见心理医生，自认已掌握主线；木兰花夜里跟踪到他，认出戒指后礼貌称雷叔，他听见同一委托人又请了她，立即感到被轻视，拒绝分享医生身份，要求她让自己做成这笔生意。她当面不争，另行调查，却发现事件已从家庭问题发展为真正的跨国绑架。雷慎行仍没有跟上变化，反而安排本社侦探藏进木兰花车内，准备以药物让她昏迷，再留下不许过问马超文的警告信；执行者被她反制，身上的名片暴露来历。木兰花因父执关系叹息，没有在本篇把他送去法办，事情也没有替他挽回声望。人物的危险是把职业尊严与独占功劳混同，懂方法却拒绝合作；父辈交情能让别人暂时宽容，不能成为他理所当然伤害晚辈的豁免。','阻挠木兰花的麻醉计划失败，助手身份被发现；未记载正式追诉及进一步结果。','严肃中年男子，戴五角形红宝石戒指，外号红星神将。','完成久违委托、恢复名声并独占调查功劳。','感觉被竞争者抢功时拒绝共享线索，甚至安排秘密阻挠。','私家侦查、监视布置和犯罪心理经验；戒指是识别标记，无特殊力量。',[(624,674,'身份、专业、戒指和排斥合作'),(1216,1236,'派助手麻醉阻挠及失败')],[('委托人同时请来更有名的同行','自认已有进展而收入名声受威胁','把合作请求视为不信任，扣住已知线索。'),('晚辈尊重旧日关系却继续调查','自己想维持独占成果','可能安排隐蔽阻挠而非公开比试。'),('案件变化超过原先判断','仍只关注谁获得功劳','会低估受害者的新危险，专业经验也因此失去作用。')],roles=['阶段性对立者'],aliases=['红星神将'],uncertainties=['未见本人直接施用药物，行动由其侦探社助手执行；不得虚构精神操纵。']),
C('boliesideng','勃列斯登','勃列斯登来自不勒斯，是红衫俱乐部的副主席与两大首脑之一，组织以精心筹划的珠宝盗卖、仿造和大型犯罪为本领，讲究体面，并不因此免于杀戮。他从成员发现的谷柏口中得知利马高原可能有巨量钻石，因谷柏神智失常不能带路，才保留马超文的生命，截走另一伙人绑架的青年，并杀掉原绑匪。他假扮印度藩王浦杰辛，借专机、招待会和礼遇转运俘虏，每逢停靠便施麻醉，又用富豪同样可能不择手段的说辞替自己的罪行辩护。木兰花在夏威夷识破他，他仍安排修甲从容周旋，实际以烟戒和金属假头皮保护反击，还提前向警方谎报有人要盗袭藩王，让真正追踪者被捕。到了高原，他能从穆秀珍对鸟鸣的反应察觉有人接应，不被激将，也不放人质远离；然而指挥部下用榴弹攻击上方，震松了自身攀附的山石。大多数同党随崩石坠落，他暂时抓住石角，木兰花救出二人后也向他抛绳，他因过于心急，未等绳到便纵身，失手坠死。最终钻石只是水泡光影，精密骗局与穷追财富都没有替他验证最初的目标。','在利马高原峭壁崩落后，急于抓救援飞索而失手坠崖死亡。','肥胖、微秃，善用印度藩王服饰伪装；藏有金属假头皮。','替红衫俱乐部夺取珠宝财富，维护斯文罪犯的自我形象。','礼貌威胁、伪造身份和借权力误导追捕；关键时不惜灭口。','珠宝鉴别与仿造经验、组织策划、手枪、烟戒与金属头部护具；不具有全身防弹。',[(1690,1784,'组织、目标、谷柏线索和控制俘虏'),(2008,2066,'烟戒、护具与反向报警'),(2328,2440,'识破暗号反应、炮击与坠死'),('木兰花全集/08雷库惊魂.txt',70,94,'副主席身份及珠宝专长的追述')],[('受害者谴责自己不择手段','想维持理直气壮的姿态','拿其他富人的污点作比较，但不真正放弃自己的罪行。'),('敌人在公众礼遇中接近','有预先可用的官方身份外衣','反向报案，让调查者被当成威胁。'),('人质对不起眼声音突然反应','自己仍能控制距离','会警觉暗中联络、限制移动，而不是只靠听懂密码。')],roles=['反派'],aliases=['不勒斯的勃列斯登','浦杰辛藩王（冒充身份）'],scores={**GUN,'combat':4},tier='并',revive=True,limits='烟戒与金属假头皮需实际佩戴，头皮被枪托敲击未损是实证，能否挡子弹只是木兰花推测。大规模人手、飞机与榴弹发射器均属具体任务配置，不是随身无限资源。'),
C('banji','班姬','班姬是陪在假印度藩王身边的印度女郎，名字在夏威夷套房事件中由勃列斯登亲口叫出。她看似正在替尊贵客人修剪指甲，使这个被外交礼遇包围的场景更像一次普通旅行；木兰花闯入揭穿身份，护卫涌进来，她也显得慌张，并没有如首领那样从容。勃列斯登让护卫退回，仍叫她继续修甲，她拾起修甲刀，留在近旁，这个低调位置让她不必先成为对手注意的中心。随后首领用烟戒和护具发动反击，木兰花将他摔开准备退向阳台，班姬突然用小巧手枪堵住去路，说明她不是只在现场受雇的无知旁观者，而能在骗局暴露后主动配合武装围堵。木兰花拉下整幅窗帘罩住她，趁她视线受阻翻出玻璃门，班姬没能完成拦截。之后她没有被单独点名，不能把高原上每名匪徒的死都算到她身上，也不能补成潜伏多年、擅长色诱或有高强武术的间谍。卡片所保留的是在服务外观之下等待时机、听首领指令行动，以及突袭条件被遮蔽物打断后仍受普通身体限制的具体行为。','夏威夷套房中持枪拦截失败，被窗帘罩住后未再单独交代下落。','印度女郎，在套房中替勃列斯登修甲，突发冲突时神色慌张。','协助勃列斯登维持藩王伪装，并阻止追踪者脱身。','先保持服务者外观，首领反击时从退路位置取枪封锁。','小型手枪和近处伪装配合；未显示精确射击或高阶格斗。',[(2008,2018,'姓名、修甲外观与紧张'),(2032,2044,'配合反击、持枪封路与被遮蔽')],[('同伴的伪装在面前被揭穿','首领仍要求维持正常行为','即使紧张也会按命令继续手边工作。'),('对手正忙于与首领搏斗','自己接近其退路且有武器','利用被忽略的位置突然封锁出口。'),('枪口威胁依赖眼前视线','近处有可被对手扯下的遮蔽物','可能被普通环境物品打断，不能隔物自动锁定。')],roles=['反派'],scores={'physical':2,'energy':0,'scope':1,'sustain':1,'range':2,'combat':1},tier='并',uncertainties=['没有她随队到高原或在那里死亡的明确证据。'])],cast=['mu_lanhua','mu_xiuzhen','gao_xiang','fang_director','ma_chaowen','ma_duolu','mrs_ma'],excluded=[{'name':'谷柏·汉烈','reason':'以他人转述提供探险、救助和钻石线索，无本书当前主角行动线；未证实为反派，也不凭精神失常推定危险立场。'},{'name':'刀疤脸、原绑架者、雷氏侦探社助手、马家保镖、夏威夷误捕警员','reason':'一次性执行者或误判者，主要动作已附属于明确的策划者和事件，不独立扩写。'}],notes=['马超文、马多禄和马夫人在后续书中实际出场，将用固定ID合并为系列卡。所谓满溪钻石最终为阳光下的水泡，不能变成任何人物的永久财产或地质发现。'])
(P/'mulanhua_f.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
